import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';

const root = process.cwd();
const outputPath = path.join(root, 'public/app.js');
const sourceFiles = [
  'src/ui/dom.js',
  'src/constants.js',
  'src/data/emoji_words.js',
  'src/data/cvc_words.js',
  'src/data/clock_hours.js',
  'src/data/math_problems.js',
  'src/core/storage.js',
  'src/core/state.js',
  'src/core/sampler.js',
  'src/core/rewards.js',
  'src/core/timer.js',
  'src/core/tts.js',
  'src/ui/confetti.js',
  'src/ui/overlay.js',
  'src/ui/trophy.js',
  'src/modes/emoji.js',
  'src/modes/cvc.js',
  'src/modes/clock.js',
  'src/modes/math.js',
  'src/router.js',
  'src/main.js',
];

const sections = await Promise.all(sourceFiles.map(async (relativePath) => {
  const source = await readFile(path.join(root, relativePath), 'utf8');
  const bundledSource = source
    .replace(/^\uFEFF/, '')
    .replace(/^import\s+.+?;\s*$/gm, '')
    .replace(/^export\s+/gm, '');

  if (/^\s*(import|export)\b/m.test(bundledSource)) {
    throw new Error(`${relativePath} bevat module-syntax die de browserbundler niet verwerkt.`);
  }

  return `\n/* ${relativePath} */\n${bundledSource.trim()}\n`;
}));

const bundle = [
  '// Generated by scripts/build-browser-bundle.mjs. Do not edit directly.',
  '(function () {',
  "  'use strict';",
  ...sections,
  '})();',
  '',
].join('\n');

if (process.argv.includes('--check')) {
  const currentBundle = await readFile(outputPath, 'utf8').catch(() => '');

  if (currentBundle !== bundle) {
    throw new Error('public/app.js is verouderd. Voer `node scripts/build-browser-bundle.mjs` uit.');
  }

  console.log('Browser bundle is up-to-date.');
} else {
  await writeFile(outputPath, bundle, 'utf8');
  console.log('Built public/app.js.');
}
